source('mp10_hypothesis_followup_v2/scripts/common.R');suppressPackageStartupMessages(library(edgeR))
# Descriptive molecular readouts, selected by reaction/transport roles, no new single-gene association tests.
genes<-c('ABCA1','ABCG1','APOE','LDLR','SCARB1','CD36','SLC27A1','SLC27A4','FABP4','FABP5','FASN','ACACA','SCD','SREBF1','SREBF2','NECTIN2','PVR','FLT1','KDR');write_json(list(genes=genes,scope='descriptive original counts/detection/normalized RNA only, no data-selected gene tests; selected before reading these readouts',time=as.character(Sys.time())),file.path(B,'config/descriptive_readouts.json'),pretty=TRUE)
b<-qread(file.path(OLD,'objects/pseudobulk.qs'),nthreads=1);pr<-b$profiles[profile_type%in%c('Epi_all','H05','L50','H10','H50','Treg','Capillary EC')];keep<-intersect(genes,rownames(b$counts));cc<-as.matrix(b$counts[keep,pr$profile_id,drop=FALSE]);de<-as.matrix(b$detected_cells[keep,pr$profile_id,drop=FALSE]);nm<-as.matrix(b$normalized_sum[keep,pr$profile_id,drop=FALSE]);z<-as.data.table(as.table(cc));setnames(z,c('gene','profile_id','raw_counts'));z[,`:=`(detected_cells=as.vector(de),normalized_sum=as.vector(nm))];z<-merge(z,pr,by='profile_id');z[,`:=`(detected_fraction=detected_cells/n_cells,mean_normalized_RNA=normalized_sum/n_cells)];put(z,'descriptive_molecular_readouts.tsv.gz');put(data.table(gene=genes,in_source=genes%in%rownames(b$counts),status=ifelse(genes%in%rownames(b$counts),'measured','not_in_feature_universe')),'descriptive_gene_coverage.tsv')
# Explicitly separate ACAT2 acetyl-CoA acetyltransferase from SOAT2: no synonym substitution.
put(data.table(requested=c('ACAT2','SOAT2','NECTIN2','PVRL2'),in_source=c('ACAT2','SOAT2','NECTIN2','PVRL2')%in%rownames(b$counts),handling=c('frozen MP10 gene; never map to SOAT2','distinct gene; not MP10 ACAT2','use frozen exact name','alias audit only; never double-count NECTIN2')),'critical_symbol_audit.tsv')
# Per-dataset old M0073 exposure range and own-count gene direction, no patient-level P manufactured.
o<-qread(file.path(OLD,'objects/model_parts/M0073.qs'),nthreads=1);p<-o$profiles;put(p[,.(n=.N,Q50_min=min(Q50),Q50_max=max(Q50),Q50_SD=sd(Q50),n_cells_min=min(n_cells),n_cells_max=max(n_cells)),by=dataset],'EC_M0073_dataset_exposure.tsv');g<-rd('hallmark_gene_sets.tsv.gz')[signature=='HALLMARK_MTORC1_SIGNALING',gene];g<-intersect(g,rownames(o$logCPM));d<-rbindlist(lapply(unique(p$dataset),function(ds){pp<-p[dataset==ds];rbindlist(lapply(g,function(gn){yy<-o$logCPM[gn,pp$profile_id];data.table(dataset=ds,gene=gn,n_specimens=nrow(pp),beta_descriptive=if(nrow(pp)>=2&&sd(pp$Q50_z)>0)coef(lm(yy~pp$Q50_z))[2]else NA_real_,status=if(nrow(pp)>=2&&sd(pp$Q50_z)>0)'descriptive_direction_only'else'not_evaluable')}))}));put(d,'EC_mTORC1_within_dataset_gene_direction.tsv.gz')
